@module(name='threshold_checker', config={
    'threshold': {
        'type': 'int',
        'default': 30,
        'description': 'The threshold value to compare against'
    },
    'monitored_value': {
        'type': 'int',
        'default': 0,
        'description': 'The value to check against the threshold'
    }
})
def run(config):
    """
    Reads a threshold from config with a default of 30 and logs a warning
    if a monitored value exceeds it.
    """
    import logging

    threshold = config['threshold']
    monitored_value = config['monitored_value']

    if monitored_value > threshold:
        logging.warning(
            f"Value {monitored_value} exceeds threshold {threshold}"
        )
